package ee.schimke.composeai.rcembedded.jvm

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.remote.core.CoreDocument
import androidx.compose.remote.core.SystemClock
import androidx.compose.remote.core.operations.Theme
import androidx.compose.ui.ImageComposeScene
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.Density
import org.jetbrains.skia.Data
import org.jetbrains.skia.EncodedImageFormat
import org.jetbrains.skia.FontMgr
import org.jetbrains.skia.Typeface

/**
 * A rendered frame together with the document that produced it.
 *
 * [renderRemoteDocumentToPng] returns pixels and nothing else, which is all the `rc-compare` lanes
 * ever wanted. A conformance run wants more: the corpus asserts the *laid-out component tree* in
 * most of its golds, and AndroidX's own `CoreDocument` already carries it —
 * `getRootLayoutComponent` and `Component.getX/getY/getWidth/getHeight` are public, and the
 * component class names are the very vocabulary the corpus is written in, because that is where it
 * came from.
 *
 * So this is not a second renderer. It is the same render, handing back the document it was
 * measured on so a caller can read what AndroidX decided.
 */
public class RcJvmRenderedDocument
internal constructor(public val document: CoreDocument, public val png: ByteArray)

/**
 * Instances [ttf] as the face that answers for every family the document names.
 *
 * Both entry points below take the font as **bytes** rather than a `Typeface`, so a caller needs no
 * skiko types of its own; the conformance lane hands over the corpus's `fonts/Ahem.ttf` and nothing
 * else in this module has to know what Ahem is.
 */
private fun pinnedFace(ttf: ByteArray?): Typeface? = ttf?.let {
  FontMgr.default.makeFromData(Data.makeFromBytes(it))
}

/**
 * Renders [bytes] and returns the laid-out document alongside the frame.
 *
 * This exists for the conformance lane in `:rc-conformance`, which measures this player as the
 * **reference** the CMP player is compared against — the corpus was generated by AndroidX, so a
 * disagreement between the two says something quite different depending on which side the corpus
 * agrees with. Keep it a thin wrapper: the moment this starts differing from
 * [renderRemoteDocumentToPng] in how it sets the document up, the reference stops being a
 * reference.
 */
public fun renderRemoteDocumentForInspection(
  bytes: ByteArray,
  widthPx: Int,
  heightPx: Int,
  density: Float = 1f,
  theme: Int = Theme.LIGHT,
  pinnedFontTtf: ByteArray? = null,
): RcJvmRenderedDocument {
  val document = parseDocument(bytes)
  val face = pinnedFace(pinnedFontTtf)
  val scene =
    ImageComposeScene(width = widthPx, height = heightPx, density = Density(density)) {
      RcPlayerJvm(document, Modifier.fillMaxSize(), theme = theme, pinnedTypeface = face)
    }
  return try {
    val image = scene.render()
    val data =
      checkNotNull(image.encodeToData(EncodedImageFormat.PNG)) {
        "skiko declined to encode the inspected frame"
      }
    RcJvmRenderedDocument(document, data.bytes)
  } finally {
    scene.close()
  }
}

/**
 * A document laid out by AndroidX's own measure pass, and whether that layout can be trusted.
 *
 * [measuredComplexText] is not a detail. When it is set, the pass asked [MeasuringPaintContext] for
 * a wrapped multi-line layout it cannot produce, so at least one component measured against empty
 * text and the geometry below is wrong in a way no diff can distinguish from a real layout
 * disagreement. A caller must report the tree as unobserved rather than compare it.
 */
public class RcJvmLaidOutDocument
internal constructor(public val document: CoreDocument, public val measuredComplexText: Boolean)

/**
 * Lays [bytes] out at the given viewport through **AndroidX's own** measure pass, and hands back
 * the document so a caller can read what AndroidX decided.
 *
 * ### Why this is separate from [renderRemoteDocumentForInspection]
 *
 * That function renders: it stands the document up on a Compose scene and `RcPlayerJvm` walks the
 * operations and draws them. It is a faithful renderer and it is *not* AndroidX's layout — the
 * `Component` geometry on the returned document is never assigned, which is why the conformance
 * lane could report `raster` from it and not `tree`.
 *
 * This runs `CoreDocument.paint`, which is where AndroidX measures and places its components. The
 * paint context is a measure-only one, so nothing is drawn; the point is the side effect the corpus
 * asserts, not the pixels.
 *
 * Keep the two side by side rather than merging them. They answer different questions — *what does
 * AndroidX draw* and *what does AndroidX decide* — and a lane that conflated them would be
 * comparing one player's pixels against another's layout.
 */
public fun layoutRemoteDocumentForInspection(
  bytes: ByteArray,
  widthPx: Int,
  heightPx: Int,
  density: Float = 1f,
  theme: Int = Theme.LIGHT,
  pinnedFontTtf: ByteArray? = null,
): RcJvmLaidOutDocument {
  val document = parseDocument(bytes)
  val context =
    initDrawContext(
      document = document,
      clock = SystemClock(),
      density = density,
      fontScale = 1f,
      seeds = emptyMap(),
      theme = theme,
      systemColorLookup = { null },
      pinnedTypeface = pinnedFace(pinnedFontTtf),
    )
  val paintContext = MeasuringPaintContext(context)
  context.setPaintContext(paintContext)
  // The viewport goes on both: `CoreDocument` measures against its own width and height, while a
  // document reading `ID_WINDOW_WIDTH` resolves it from the context. Setting one and not the other
  // lays out at one size and computes expressions at another.
  document.setWidth(widthPx)
  document.setHeight(heightPx)
  context.mWidth = widthPx.toFloat()
  context.mHeight = heightPx.toFloat()
  document.paint(context, theme)
  return RcJvmLaidOutDocument(document, paintContext.measuredComplexText)
}
